// encoded是把这个packages/vgraph-wasm/examples/static/dotlayout.wasm 二进制文件内容 做了 base64 文本编码 ，方便以 “TS 文件内嵌资源” 的形式携带/加载
// 用于某些场景下不方便以静态资源.wasm文件形式形式加载 wasm
// 内容就是 Graphviz dot 布局计算引擎的 wasm 运行时产物（编译后的 WebAssembly 二进制 （类似把源码编译成可执行文件/库））
const encoded =
  "";

export function load_dot_wasm_sync() {
  const data = atob(encoded);
  const bytes = new Uint8Array(data.length);
  for (let i = 0; i < data.length; i++) {
    bytes[i] = data.charCodeAt(i);
  }
  return bytes.buffer;
}
